var code = "<article class=\"article\">\r\n  <h1>2023 Джеффри Макконнелл - Анализ алгоритмов. Активный обучающий подход. 416стр</h1>\r\n  <p>Конспект книги</p>\r\n</article>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n      <a href=\"#p1\">1 Основы анализа алгоритмов (19)</a>\r\n  <br><a href=\"#p2\">2 Рекурсивные алгоритмы (45)</a>\r\n  <br><a href=\"#p3\">3 Алгоритмы поиска и выборки (73)</a>\r\n  <br><a href=\"#p4\">4 Алгоритмы сортировки (89)</a>\r\n  <br><a href=\"#p5\">5 Численные алгоритмы (141)</a>\r\n  <br><a href=\"#p6\">6 Алгоритмы формальных языков (155)</a>\r\n  <br><a href=\"#p7\">7 Алгоритмы сравнения с образцом (219)</a>\r\n  <br><a href=\"#p8\">8 Алгоритмы на графах (237)</a>\r\n  <br><a href=\"#p9\">9 Параллельные алгоритмы (268)</a>\r\n  <br><a href=\"#p10\">10 Вычислимое и невычислимое (300)</a>\r\n  <br><a href=\"#p11\">11 Другие алгоритмические инструменты (348)</a>\r\n</article>\r\n\r\n\r\n<!-- 1 Основы анализа алгоритмов (19) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p1\"></div>\r\n  <h3>1 Основы анализа алгоритмов (19)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 2 Рекурсивные алгоритмы (45) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p2\"></div>\r\n  <h3>2 Рекурсивные алгоритмы (45)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 3 Алгоритмы поиска и выборки (73) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p3\"></div>\r\n  <h3>3 Алгоритмы поиска и выборки (73)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 4 Алгоритмы сортировки (89) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p4\"></div>\r\n  <h3>4 Алгоритмы сортировки (89)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 5 Численные алгоритмы (141) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p5\"></div>\r\n  <h3>5 Численные алгоритмы (141)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 6 Алгоритмы формальных языков (155) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p6\"></div>\r\n  <h3>6 Алгоритмы формальных языков (155)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 7 Алгоритмы сравнения с образцом (219) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p7\"></div>\r\n  <h3>7 Алгоритмы сравнения с образцом (219)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 8 Алгоритмы на графах (237) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p8\"></div>\r\n  <h3>8 Алгоритмы на графах (237)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 9 Параллельные алгоритмы (268) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p9\"></div>\r\n  <h3>9 Параллельные алгоритмы (268)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 10 Вычислимое и невычислимое (300) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p10\"></div>\r\n  <h3>10 Вычислимое и невычислимое (300)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 11 Другие алгоритмические инструменты (348) -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p11\"></div>\r\n  <h3>11 Другие алгоритмические инструменты (348)</h3>\r\n\r\n</article>\r\n";
