var code = "<h1>Codewars 3 Advanced</h1>\r\n\r\n<!-- Заголовок -->\r\n<div class=\"article\">\r\n  <div class=\"anchor\" id=\"content\"></div>\r\n  <h2>Содержание</h2>\r\n</div>\r\n\r\n<!-- Содержание -->\r\n<div class=\"article article__content\">\r\n\r\n  <div>\r\n    <p><a href=\"#links\">Codewars Advanced</a></p>\r\n    <p><a href=\"#task-1\">count-strings-in-objects</a></p>\r\n  </div>\r\n\r\n</div>\r\n\r\n<!-- Знакомство с Codewars и алгоритмическими задачами -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"links\"></div>\r\n  <h2>Codewars Advanced</h2>\r\n\r\n  <p>Темы:</p>\r\n  <ol>\r\n    <li>Строки</li>\r\n    <li>Массивы</li>\r\n    <li>Методы массивов</li>\r\n    <li>Объекты</li>\r\n    <li>Рекурсия</li>\r\n    <li>typeof</li>\r\n  </ol>\r\n\r\n  <p>Ссылка на RSSchool</p>\r\n  <p><a href=\"https://github.com/rolling-scopes-school/tasks/blob/master/tasks/codewars/preschool-2022-codewars3.md\">preschool-2022-codewars3</a></p>\r\n\r\n  <p>Ссылки на Codewars</p>\r\n  <p>7 kyu <a href=\"https://www.codewars.com/kata/count-strings-in-objects\">https://www.codewars.com/kata/count-strings-in-objects</a></p>\r\n</article>\r\n\r\n\r\n<!-- count-strings-in-objects -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"task-1\"></div>\r\n  <h2>count-strings-in-objects</h2>\r\n\r\n  <p>Description</p>\r\n  <p>Create a function strCount (takes an object as argument) that will count all string values inside an object.</p>\r\n  \r\n  <details>\r\n  <summary>Solution</summary>\r\n<pre>function strCount(obj){\r\n  let count = 0;\r\n  for (key in obj) {\r\n    if (typeof obj[key] == 'string') count++;\r\n    if (typeof obj[key] == 'object') count += strCount(obj[key]);\r\n  }\r\n  return count;\r\n}</pre>\r\n  </details>\r\n</article>\r\n\r\n";
