var code = "<h1>Codewars</h1>\r\n\r\n<!-- Заголовок -->\r\n<div class=\"article\">\r\n  <div class=\"anchor\" id=\"content\"></div>\r\n  <h2>Содержание</h2>\r\n</div>\r\n\r\n<!-- Содержание -->\r\n<div class=\"article article__content\">\r\n\r\n  <div>\r\n    <p><a href=\"#fp\">Functional programming</a></p>\r\n  </div>\r\n\r\n</div>\r\n\r\n\r\n<!-- Functional programming -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"fp\"></div>\r\n  <h2>Functional programming</h2>\r\n\r\n  <p>7 kyu <a href=\"https://www.codewars.com/kata/first-class-function-factory\">https://www.codewars.com/kata/first-class-function-factory</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/javascript-from-the-inside-number-1-map\">https://www.codewars.com/kata/javascript-from-the-inside-number-1-map</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/javascript-from-the-inside-number-2-filter\">https://www.codewars.com/kata/javascript-from-the-inside-number-2-filter</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/power-bind\">https://www.codewars.com/kata/power-bind</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/closures-and-scopes\">https://www.codewars.com/kata/closures-and-scopes</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/function-composition\">https://www.codewars.com/kata/function-composition</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/function-composition-1\">https://www.codewars.com/kata/function-composition-1</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/reusable-memoisation\">https://www.codewars.com/kata/reusable-memoisation</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/once\">https://www.codewars.com/kata/once</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/multifilter\">https://www.codewars.com/kata/multifilter</a></p>\r\n  <p>6 kyu <a href=\"https://www.codewars.com/kata/combinator-flip\">https://www.codewars.com/kata/combinator-flip</a></p>\r\n  <p>5 kyu <a href=\"https://www.codewars.com/kata/function-cache\">https://www.codewars.com/kata/function-cache</a></p>\r\n  <p>5 kyu <a href=\"https://www.codewars.com/kata/a-chain-adding-function\">https://www.codewars.com/kata/a-chain-adding-function</a></p>\r\n  <p>5 kyu <a href=\"https://www.codewars.com/kata/lazy-repeater\">https://www.codewars.com/kata/lazy-repeater</a></p>\r\n  <p>4 kyu <a href=\"https://www.codewars.com/kata/currying-vs-partial-application\">https://www.codewars.com/kata/currying-vs-partial-application</a></p>\r\n</article>";
