var code = "<article class=\"article\">\r\n  <h1>2007 Яновский - Компьютерные игры на языке программирования Си. 126c</h1>\r\n  <p>Конспект книги</p>\r\n</article>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n  <p>\r\n        <a href=\"#p1\">Предисловие (4)</a>\r\n    <br><a href=\"#p2\">Введение (6)</a>\r\n    <br><a href=\"#p3\">Глава 1. Меню и не только (7)</a>\r\n    <br><a href=\"#p4\">Глава 2. Циклы и сложные программы (15)</a>\r\n    <br><a href=\"#p5\">Глава 3. Мышиная возня (50)</a>\r\n    <br><a href=\"#p6\">Глава 4. Функции (56)</a>\r\n    <br><a href=\"#p7\">Глава 5. Массивы (75)</a>\r\n    <br><a href=\"#p8\">Список рекомендуемой литературы (132)</a>\r\n  </p>\r\n</article>\r\n\r\n\r\n<!-- Список рекомендуемой литературы -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p8\"></div>\r\n  <h3>Список рекомендуемой литературы (132)</h3>\r\n\r\n  <ol>\r\n    <li>1992 Керниган, Ритчи - Язык программирования Си. 202с.</li>\r\n    <li>1992 Романовская, Русс, Свитковский - Программирование в среде Си для ПЭВМ ЕС. 352с.</li>\r\n    <li>1991 Уинер - Язык Турбо Си. 384с.</li>\r\n    <li>1994 Яншин, Калинин - Обработка изображений на языке Си для IBM PC. Алгоритмы и программы. 241с.</li>\r\n  </ol>\r\n</article>\r\n\r\n";
