var code = "<article class=\"article\">\r\n  <h1>2011 Александр Кораблин. specialist. Программирование на языке Си</h1>\r\n  <p>Конспект видео курса</p>\r\n  <p>12 уроков. Длительность 32ч 45м.</p>\r\n</article>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n      <a href=\"#p1\">1 Введение в язык Си</a>\r\n  <br><a href=\"#p2\">2 Операции</a>\r\n  <br><a href=\"#p3\">3 Операторы</a>\r\n  <br><a href=\"#p4\">4 Препроцессор</a>\r\n  <br><a href=\"#p5\">5 Функции</a>\r\n  <br><a href=\"#p6\">6 Адресная арифметика</a>\r\n  <br><a href=\"#p7\">7 Массивы</a>\r\n  <br><a href=\"#p8\">8 Классы памяти</a>\r\n  <br><a href=\"#p9\">9 Файлы</a>\r\n  <br><a href=\"#p10\">10 Составные типы данных</a>\r\n  <br><a href=\"#p11\">11 Структуры</a>\r\n  <br><a href=\"#p12\">12 Коллекции</a>\r\n</article>\r\n\r\n\r\n<!-- 1 Введение в язык Си -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p1\"></div>\r\n  <h3>1 Введение в язык Си</h3>\r\n</article>\r\n\r\n\r\n<!-- 2 Операции -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p2\"></div>\r\n  <h3>2 Операции</h3>\r\n</article>\r\n\r\n\r\n<!-- 3 Операторы -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p3\"></div>\r\n  <h3>3 Операторы</h3>\r\n</article>\r\n\r\n\r\n<!-- 4 Препроцессор -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p4\"></div>\r\n  <h3>4 Препроцессор</h3>\r\n</article>\r\n\r\n\r\n<!-- 5 Функции -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p5\"></div>\r\n  <h3>5 Функции</h3>\r\n</article>\r\n\r\n\r\n<!-- 6 Адресная арифметика -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p6\"></div>\r\n  <h3>6 Адресная арифметика</h3>\r\n</article>\r\n\r\n\r\n<!-- 7 Массивы -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p7\"></div>\r\n  <h3>7 Массивы</h3>\r\n</article>\r\n\r\n\r\n<!-- 8 Классы памяти -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p8\"></div>\r\n  <h3>8 Классы памяти</h3>\r\n</article>\r\n\r\n\r\n<!-- 9 Файлы -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p9\"></div>\r\n  <h3>9 Файлы</h3>\r\n</article>\r\n\r\n\r\n<!-- 10 Составные типы данных -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p10\"></div>\r\n  <h3>10 Составные типы данных</h3>\r\n</article>\r\n\r\n\r\n<!-- 11 Структуры -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p11\"></div>\r\n  <h3>11 Структуры</h3>\r\n</article>\r\n\r\n\r\n<!-- 12 Коллекции -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p12\"></div>\r\n  <h3>12 Коллекции</h3>\r\n</article>\r\n\r\n";
