var code = "<article class=\"article\">\r\n  <h1>2001 Симонович - Занимательное программирование: C++. Книга для детей, родителей и учителей. 368c</h1>\r\n  <p>Конспект книги</p>\r\n</article>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n      <a href=\"#p0\">От авторов (3)</a>\r\n  <br><a href=\"#p1\">1 Программирование без компьютера (7)</a>\r\n  <br><a href=\"#p2\">2 Процедуры и функции (17)</a>\r\n  <br><a href=\"#p3\">3 Как люди учились программировать компьютер (31)</a>\r\n  <br><a href=\"#p4\">4 Компьютер без программирования (45)</a>\r\n  <br><a href=\"#p5\">5 Объекты и их свойства (59)</a>\r\n  <br><a href=\"#p6\">6 C++ Builder: первое знакомство (73)</a>\r\n  <br><a href=\"#p7\">7 Простейшая программа (81)</a>\r\n  <br><a href=\"#p8\">8 Сохранение - мать учения (97)</a>\r\n  <br><a href=\"#p9\">9 Учим программу читать (107)</a>\r\n  <br><a href=\"#p10\">10 Создаем электронный альбом (117)</a>\r\n  <br><a href=\"#p11\">11 Создаем строку меню (131)</a>\r\n  <br><a href=\"#p12\">12 Программа учится сочинять (143)</a>\r\n  <br><a href=\"#p13\">13 Учим программу запоминать (157)</a>\r\n  <br><a href=\"#p14\">14 Типы данных (167)</a>\r\n  <br><a href=\"#p15\">15 Управление при помощи таймера (181)</a>\r\n  <br><a href=\"#p16\">16 Учим программу думать (193)</a>\r\n  <br><a href=\"#p17\">17 Таблица умножения (203)</a>\r\n  <br><a href=\"#p18\">18 Движение по координатам (215)</a>\r\n  <br><a href=\"#p19\">19 Осваиваем компьютерную графику (227)</a>\r\n  <br><a href=\"#p20\">20 Кнопки с рисунками в простой головоломке (243)</a>\r\n  <br><a href=\"#p21\">21 Циклы и массивы (259)</a>\r\n  <br><a href=\"#p22\">22 Еще один электронный альбом (277)</a>\r\n  <br><a href=\"#p23\">23 Изучаем список флажков (293)</a>\r\n  <br><a href=\"#p24\">24 Разыгрываем сражение (303)</a>\r\n  <br><a href=\"#p25\">25 Головоломка на флажках (321)</a>\r\n  <br><a href=\"#p26\">26 Компьютер рисует узоры (331)</a>\r\n</article>\r\n\r\n\r\n<!-- От авторов -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p0\"></div>\r\n  <h3>От авторов (3)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 1 Программирование без компьютера -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p1\"></div>\r\n  <h3>1 Программирование без компьютера (7)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 2 Процедуры и функции -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p2\"></div>\r\n  <h3>2 Процедуры и функции (17)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 3 Как люди учились программировать компьютер -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p3\"></div>\r\n  <h3>3 Как люди учились программировать компьютер (31)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 4 Компьютер без программирования -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p4\"></div>\r\n  <h3>4 Компьютер без программирования (45)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 5 Объекты и их свойства -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p5\"></div>\r\n  <h3>5 Объекты и их свойства (59)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 6 C++ Builder: первое знакомство -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p6\"></div>\r\n  <h3>6 C++ Builder: первое знакомство (73)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 7 Простейшая программа -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p7\"></div>\r\n  <h3>7 Простейшая программа (81)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 8 Сохранение - мать учения -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p8\"></div>\r\n  <h3>8 Сохранение - мать учения (97)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 9 Учим программу читать -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p9\"></div>\r\n  <h3>9 Учим программу читать (107)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 10 Создаем электронный альбом -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p10\"></div>\r\n  <h3>10 Создаем электронный альбом (117)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 11 Создаем строку меню -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p11\"></div>\r\n  <h3>11 Создаем строку меню (131)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 12 Программа учится сочинять -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p12\"></div>\r\n  <h3>12 Программа учится сочинять (143)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 14 Типы данных -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p14\"></div>\r\n  <h3>14 Типы данных (167)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 15 Управление при помощи таймера -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p15\"></div>\r\n  <h3>15 Управление при помощи таймера (181)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 16 Учим программу думать -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p16\"></div>\r\n  <h3>16 Учим программу думать (193)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 17 Таблица умножения -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p17\"></div>\r\n  <h3>17 Таблица умножения (203)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 18 Движение по координатам -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p18\"></div>\r\n  <h3>18 Движение по координатам (215)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 19 Осваиваем компьютерную графику -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p19\"></div>\r\n  <h3>19 Осваиваем компьютерную графику (227)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 20 Кнопки с рисунками в простой головоломке -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p20\"></div>\r\n  <h3>20 Кнопки с рисунками в простой головоломке (243)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 21 Циклы и массивы -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p21\"></div>\r\n  <h3>21 Циклы и массивы (259)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 22 Еще один электронный альбом -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p22\"></div>\r\n  <h3>22 Еще один электронный альбом (277)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 23 Изучаем список флажков -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p23\"></div>\r\n  <h3>23 Изучаем список флажков (293)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 24 Разыгрываем сражение -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p24\"></div>\r\n  <h3>24 Разыгрываем сражение (303)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 25 Головоломка на флажках -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p25\"></div>\r\n  <h3>25 Головоломка на флажках (321)</h3>\r\n\r\n</article>\r\n\r\n\r\n<!-- 26 Компьютер рисует узоры -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"p26\"></div>\r\n  <h3>26 Компьютер рисует узоры (331)</h3>\r\n\r\n</article>\r\n\r\n";
