// Module
var code = "<h1>Справочник по HTML тегам</h1>\r\n\r\n<!-- Заголовок -->\r\n<div class=\"article\">\r\n  <div class=\"anchor\" id=\"contents\"></div>\r\n  <h2>Содержание</h2>\r\n</div>\r\n\r\n<!-- Содержание -->\r\n<div class=\"article__contents\">\r\n\r\n  <div>\r\n    <p><a href=\"#links\">links</a></p>\r\n    <p><a href=\"#info\">info</a></p>\r\n    <p><a href=\"#single\">Одиночные</a></p>\r\n    <p><a href=\"#semantic\">Семантические</a></p>\r\n    <p><a href=\"#html5\">HTML5</a></p>\r\n    <p><a href=\"#block\">Блочные</a></p>\r\n    <p><a href=\"#inline\">Строчные</a></p>\r\n    <p><a href=\"#no-standard\">Нестандартные</a></p>\r\n    <p><a href=\"#obsolete-elements\">Осуждаемые</a></p>\r\n    <br>\r\n    <p><a href=\"#doctype\">&lt;!DOCTYPE&gt;</a></p>\r\n    <p><a href=\"#comment\">&lt;!--...--&gt;</a></p>\r\n    <p><a href=\"#tag-html\">&lt;html&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#base-elements\">Базовые<br>элементы</a>\r\n    <br><a href=\"#tag-head\">&lt;head&gt;</a>\r\n    <br><a href=\"#tag-body\">&lt;body&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#metadata\">Метаданные</a>\r\n    <br><a href=\"#tag-meta\">&lt;meta /&gt;</a>\r\n    <br><a href=\"#tag-base\">&lt;base /&gt;</a>\r\n    <br><a href=\"#tag-link\">&lt;link /&gt;</a>\r\n    <br><a href=\"#tag-title\">&lt;title&gt;</a>\r\n    <br><a href=\"#tag-style\">&lt;style&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#section-elements\">Секции</a>\r\n    <br><a href=\"#tag-header\">&lt;header&gt;</a>\r\n    <br><a href=\"#tag-nav\">&lt;nav&gt;</a>\r\n    <br><a href=\"#tag-aside\">&lt;aside&gt;</a>\r\n    <br><a href=\"#tag-main\">&lt;main&gt;</a>\r\n    <br><a href=\"#tag-article\">&lt;article&gt;</a>\r\n    <br><a href=\"#tag-section\">&lt;section&gt;</a>\r\n    <br><a href=\"#tag-adress\">&lt;adress&gt;</a>\r\n    <br><a href=\"#tag-footer\">&lt;footer&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#container-elements\">Контейнер</a>\r\n    <br><a href=\"#tag-div\">&lt;div&gt;</a>\r\n    <br><a href=\"#tag-span\">&lt;span&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#headings\">Заголовки</a>\r\n    <br><a href=\"#tag-hgroup\">&lt;hgroup&gt;</a>\r\n    <br><a href=\"#tag-h1\">&lt;h1&gt;</a>\r\n    <br><a href=\"#tag-h2\">&lt;h2&gt; - &lt;h6&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#text-elements1\">Оформление<br>текста</a>\r\n    <br><a href=\"#tag-a\">&lt;a&gt;</a>\r\n    <br><a href=\"#tag-hr\">&lt;hr /&gt;</a>\r\n    <br><a href=\"#tag-p\">&lt;p&gt;</a>\r\n    <br><a href=\"#tag-pre\">&lt;pre&gt;</a>\r\n    <br><a href=\"#tag-br\">&lt;br /&gt;</a>\r\n    <br><a href=\"#tag-wbr\">&lt;wbr /&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#text-elements2\">Выделение<br>текста</a>\r\n    <br><a href=\"#tag-b\">&lt;b&gt;</a>\r\n    <br><a href=\"#tag-i\">&lt;i&gt;</a>\r\n    <br><a href=\"#tag-s\">&lt;s&gt;</a>\r\n    <br><a href=\"#tag-u\">&lt;u&gt;</a>\r\n    <br><a href=\"#tag-del\">&lt;del&gt;</a>\r\n    <br><a href=\"#tag-ins\">&lt;ins&gt;</a>\r\n    <br><a href=\"#tag-mark\">&lt;mark&gt;</a>\r\n    <br><a href=\"#tag-small\">&lt;small&gt;</a>\r\n    <br><a href=\"#tag-sup\">&lt;sup&gt;</a>\r\n    <br><a href=\"#tag-sub\">&lt;sub&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#text-elements3\">Значение<br>текста</a>\r\n    <br><a href=\"#tag-abbr\">&lt;abbr&gt;</a>\r\n    <br><a href=\"#tag-code\">&lt;code&gt;</a>\r\n    <br><a href=\"#tag-data\">&lt;data&gt;</a>\r\n    <br><a href=\"#tag-dfn\">&lt;dfn&gt;</a>\r\n    <br><a href=\"#tag-em\">&lt;em&gt;</a>\r\n    <br><a href=\"#tag-kbd\">&lt;kbd&gt;</a>\r\n    <br><a href=\"#tag-samp\">&lt;samp&gt;</a>\r\n    <br><a href=\"#tag-strong\">&lt;strong&gt;</a>\r\n    <br><a href=\"#tag-time\">&lt;time&gt;</a>\r\n    <br><a href=\"#tag-var\">&lt;var&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#text-elements4\">Цитаты</a>\r\n    <br><a href=\"#tag-blockquote\">&lt;blockquote&gt;</a>\r\n    <br><a href=\"#tag-q\">&lt;q&gt;</a>\r\n    <br><a href=\"#tag-cite\">&lt;cite&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#text-elements5\">Направление<br>текста</a>\r\n    <br><a href=\"#tag-bdi\">&lt;bdi&gt;</a>\r\n    <br><a href=\"#tag-tbdo\">&lt;tbdo&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#text-elements6\">Аннотация</a>\r\n    <br><a href=\"#tag-ruby\">&lt;ruby&gt;</a>\r\n    <br><a href=\"#tag-rt\">&lt;rt&gt;</a>\r\n    <br><a href=\"#tag-rp\">&lt;rp&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#list-elements\">Список</a>\r\n    <br><a href=\"#tag-ol\">&lt;ol&gt;</a>\r\n    <br><a href=\"#tag-ul\">&lt;ul&gt;</a>\r\n    <br><a href=\"#tag-li\">&lt;li&gt;</a>\r\n    <br><a href=\"#tag-dl\">&lt;dl&gt;</a>\r\n    <br><a href=\"#tag-dt\">&lt;dt&gt;</a>\r\n    <br><a href=\"#tag-dd\">&lt;dd&gt;</a>\r\n    <br><a href=\"#tag-menu\">&lt;menu&gt;</a>\r\n    <br><a href=\"#tag-command\">&lt;command&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#table-elements\">Таблица</a>\r\n    <br><a href=\"#tag-table\">&lt;table&gt;</a>\r\n    <br><a href=\"#tag-caption\">&lt;caption&gt;</a>\r\n    <br><a href=\"#tag-colgroup\">&lt;colgroup&gt;</a>\r\n    <br><a href=\"#tag-col\">&lt;col&gt;</a>\r\n    <br><a href=\"#tag-thead\">&lt;thead&gt;</a>\r\n    <br><a href=\"#tag-tfoot\">&lt;tfoot&gt;</a>\r\n    <br><a href=\"#tag-tbody\">&lt;tbody&gt;</a>\r\n    <br><a href=\"#tag-tr\">&lt;tr&gt;</a>\r\n    <br><a href=\"#tag-th\">&lt;th&gt;</a>\r\n    <br><a href=\"#tag-td\">&lt;td&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#form-elements\">Форма</a>\r\n    <br><a href=\"#tag-form\">&lt;form&gt;</a>\r\n    <br><a href=\"#tag-fieldset\">&lt;fieldset&gt;</a>\r\n    <br><a href=\"#tag-legend\">&lt;legend&gt;</a>\r\n    <br><a href=\"#tag-input\">&lt;input&gt;</a>\r\n    <br><a href=\"#tag-datalist\">&lt;datalist&gt;</a>\r\n    <br><a href=\"#tag-label\">&lt;label&gt;</a>\r\n    <br><a href=\"#tag-textarea\">&lt;textarea&gt;</a>\r\n    <br><a href=\"#tag-select\">&lt;select&gt;</a>\r\n    <br><a href=\"#tag-optgroup\">&lt;optgroup&gt;</a>\r\n    <br><a href=\"#tag-meter\">&lt;meter&gt;</a>\r\n    <br><a href=\"#tag-progress\">&lt;progress&gt;</a>\r\n    <br><a href=\"#tag-button\">&lt;button&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#embed-elements\">Встраиваемый<br>контент</a>\r\n    <br><a href=\"#tag-img\">&lt;img /&gt;</a>\r\n    <br><a href=\"#tag-area\">&lt;area /&gt;</a>\r\n    <br><a href=\"#tag-picture\">&lt;picture&gt;</a>\r\n    <br><a href=\"#tag-source\">&lt;source&gt;</a>\r\n    <br><a href=\"#tag-figure\">&lt;figure&gt;</a>\r\n    <br><a href=\"#tag-figcaption\">&lt;figcaption&gt;</a>\r\n    <br><a href=\"#tag-iframe\">&lt;iframe&gt;</a>\r\n    <br><a href=\"#tag-embed\">&lt;embed&gt;</a>\r\n    <br><a href=\"#tag-object\">&lt;object&gt;</a>\r\n    <br><a href=\"#tag-param\">&lt;param&gt;</a>\r\n    <br><a href=\"#tag-video\">&lt;video&gt;</a>\r\n    <br><a href=\"#tag-audio\">&lt;audio&gt;</a>\r\n    <br><a href=\"#tag-track\">&lt;track&gt;</a>\r\n    <br><a href=\"#tag-map\">&lt;map&gt;</a>\r\n    <br><a href=\"#tag-use\">&lt;use&gt;</a>\r\n    <br><a href=\"#tag-svg\">&lt;svg&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#interactive-elements\">Интерактивные<br>элементы</a>\r\n    <br><a href=\"#tag-dialog\">&lt;dialog&gt;</a>\r\n    <br><a href=\"#tag-details\">&lt;details&gt;</a>\r\n    <br><a href=\"#tag-summary\">&lt;summary&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#script-elements\">Скрипты</a>\r\n    <br><a href=\"#tag-script\">&lt;script&gt;</a>\r\n    <br><a href=\"#tag-noscript\">&lt;noscript&gt;</a>\r\n    <br><a href=\"#tag-canvas\">&lt;canvas&gt;</a></p>\r\n    <br>\r\n    <p><a href=\"#web-elements\">Веб-компоненты</a>\r\n    <br><a href=\"#tag-template\">&lt;template&gt;</a>\r\n    <br><a href=\"#tag-slot\">&lt;slot&gt;</a></p>\r\n  </div>\r\n\r\n  <div>\r\n    <p><a href=\"#obsolete-elements\">Устаревшие</a>\r\n    <br><a href=\"#tag-acronym\">&lt;acronym&gt;</a>\r\n    <br><a href=\"#tag-applet\">&lt;applet&gt;</a>\r\n    <br><a href=\"#tag-basefont\">&lt;basefont&gt;</a>\r\n    <br><a href=\"#tag-bgsound\">&lt;bgsound&gt;</a>\r\n    <br><a href=\"#tag-big\">&lt;big&gt;</a>\r\n    <br><a href=\"#tag-blink\">&lt;blink&gt;</a>\r\n    <br><a href=\"#tag-center\">&lt;center&gt;</a>\r\n    <br><a href=\"#tag-content\">&lt;content&gt;</a>\r\n    <br><a href=\"#tag-dir\">&lt;dir&gt;</a>\r\n    <br><a href=\"#tag-font\">&lt;font&gt;</a>\r\n    <br><a href=\"#tag-frame\">&lt;frame&gt;</a>\r\n    <br><a href=\"#tag-frameset\">&lt;frameset&gt;</a>\r\n    <br><a href=\"#tag-image\">&lt;image&gt;</a>\r\n    <br><a href=\"#tag-keygen\">&lt;keygen&gt;</a>\r\n    <br><a href=\"#tag-marquee\">&lt;marquee&gt;</a>\r\n    <br><a href=\"#tag-menuitem\">&lt;menuitem&gt;</a>\r\n    <br><a href=\"#tag-nobr\">&lt;nobr&gt;</a>\r\n    <br><a href=\"#tag-noembed\">&lt;noembed&gt;</a>\r\n    <br><a href=\"#tag-noframes\">&lt;noframes&gt;</a>\r\n    <br><a href=\"#tag-plaintext\">&lt;plaintext&gt;</a>\r\n    <br><a href=\"#tag-rb\">&lt;rb&gt;</a>\r\n    <br><a href=\"#tag-rtc\">&lt;rtc&gt;</a>\r\n    <br><a href=\"#tag-spacer\">&lt;spacer&gt;</a>\r\n    <br><a href=\"#tag-strike\">&lt;strike&gt;</a>\r\n    <br><a href=\"#tag-tt\">&lt;tt&gt;</a>\r\n    <br><a href=\"#tag-xmp\">&lt;xmp&gt;</a></p>\r\n  </div>\r\n</div>\r\n\r\n<!-- links-->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"links\"></div>\r\n  <h2>links</h2>\r\n\r\n  <p><a href=\"https://htmlbook.ru/html\">htmlbook.ru/html</a> Справочник по HTML (Влад Мержевич)</p>\r\n  <p><a href=\"https://webref.ru/html\">webref.ru/html</a> Справочник HTML</p>\r\n  <p><a href=\"https://html5css.ru/tags/default.php\">html5css.ru/tags</a> HTML Справочник всех тегов онлайн и примеры</p>\r\n  <p><a href=\"https://htmlbase.ru/\">htmlbase.ru</a> HTMLBASE - самый современный справочник по HTML и CSS</p>\r\n  <p><a href=\"https://guruweba.com/html/\">guruweba.com/html</a> Справочник тегов HTML</p>\r\n  <p><a href=\"https://ru.w3docs.com/uchebnik-html.html\">ru.w3docs.com/uchebnik-html.html</a> Учебник HTML</p>\r\n  <p><a href=\"https://hcdev.ru/html/\">hcdev.ru/html</a> Справочник HTML</p>\r\n  <p><a href=\"https://htmlacademy.ru/blog/html-tags/book\">htmlacademy.ru/blog/html-tags/book</a> справочник по html</p>\r\n  <p><a href=\"https://developer.mozilla.org/en-US/docs/Web/HTML/Reference\">developer.mozilla.org</a> HTML Reference</p>\r\n  <p><a href=\"https://doka.guide/html/\">doka.guide/html</a> HTML</p>\r\n  <p><a href=\"https://htmlcheatsheet.com/\">htmlcheatsheet.com</a> htmlcheatsheet</p>\r\n  <p><a href=\"https://www.htmlquick.com/reference/tags.html\">htmlquick.com/reference/tags.html</a></p>\r\n  <p><a href=\"https://html.spec.whatwg.org/multipage/\">html.spec.whatwg.org</a> HTML Living standart</p>\r\n  <p><a href=\"https://htmlreference.io/\">htmlreference.io</a> HTML Reference</p>\r\n</article>\r\n\r\n<!-- info-->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"info\"></div>\r\n  <h2>info</h2>\r\n\r\n  <p>Всего в HTML 110 элементов - 2 без тегов (доктайп, комментарий), 15 с одиночным тегом, 93 с парными тегами. </p>\r\n\r\n  <hr>\r\n\r\n  <p><b>Элемент с одиночным тегом</b> называется пустым (empty element). Он не имеет содержимого и закрывающего тега, а состоит только из открывающего тега.</p>\r\n  <p><b>Элемент с парными тегами</b> состоит из открывающего тега (start tag), содержимого (content) и закрывающего тега (end tag).</p>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"single\"></div>\r\n  <h2>Элементы с одиночным тегом (15)</h2>\r\n\r\n  <p>\r\n  <strong>&lt;area /&gt;</strong>&nbsp;\r\n  <strong>&lt;base /&gt;</strong>&nbsp;\r\n  <strong>&lt;br /&gt;</strong>&nbsp;\r\n  <strong>&lt;col /&gt;</strong>&nbsp;\r\n  <strong>&lt;embed /&gt;</strong>&nbsp;\r\n  <strong>&lt;hr /&gt;</strong>&nbsp;\r\n  <strong>&lt;img /&gt;</strong>&nbsp;\r\n  <strong>&lt;input /&gt;</strong>&nbsp;\r\n  <strong>&lt;keygen /&gt;</strong>&nbsp;\r\n  <strong>&lt;link /&gt;</strong>&nbsp;\r\n  <strong>&lt;meta /&gt;</strong>&nbsp;\r\n  <strong>&lt;param /&gt;</strong>&nbsp;\r\n  <strong>&lt;source /&gt;</strong>&nbsp;\r\n  <strong>&lt;track /&gt;</strong>&nbsp;\r\n  <strong>&lt;wbr /&gt;</strong>\r\n  </p>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"semantic\"></div>\r\n  <h2>Семантические теги (15)</h2>\r\n  <p>\r\n    <strong>&lt;address&gt;</strong>\r\n    <strong>&lt;article&gt;</strong>\r\n    <strong>&lt;aside&gt;</strong>\r\n    <strong>&lt;bdi&gt;</strong>\r\n    <strong>&lt;figcaption&gt;</strong>\r\n    <strong>&lt;figure&gt;</strong>\r\n    <strong>&lt;footer&gt;</strong>\r\n    <strong>&lt;header&gt;</strong>\r\n    <strong>&lt;main&gt;</strong>\r\n    <strong>&lt;mark&gt;</strong>\r\n    <strong>&lt;nav&gt;</strong>\r\n    <strong>&lt;section&gt;</strong>\r\n    <strong>&lt;time&gt;</strong>\r\n    <strong>&lt;wbr&gt;</strong>\r\n  </p>\r\n  <p>Семантические теги появились в HTML5. До их появления вся разметка веб-страниц строилась при помощи элементов &lt;div&gt;, которым присваивались идентификаторы (id) или классы (class). Они нужны для группировки контента и разметки текстового содержимого. Они четко описывают, какой контент содержат.</p>\r\n  <p>Элемент <strong>&lt;address&gt;</strong> определяет контактную информацию автора/владельца документа или статьи.</p>\r\n  <p>Элемент <strong>&lt;article&gt;</strong> определяет независимый блок, в котором группируются записи (статьи, публикации в блоге, комментарии и т.д).</p>\r\n  <p>Элемент <strong>&lt;aside&gt;</strong> oн определяет раздел, в котором содержится информация, дополняющая основной отдел. Эта информация является факультативной, и если ее удалить, основное содержимое не пострадает. Такой информацией могут быть комментарии, справочная информация, списки терминов, коллекция ссылок и т.д.</p>\r\n  <p>Элемент <strong>&lt;header&gt;</strong> формирует заголовочный блок или “шапку” документа, используется как контейнер для группировки вводных и навигационных элементов (логотип, навигационное меню, форма поиска и т.д.).</p>\r\n  <p>Элемент <strong>&lt;bdi&gt;</strong> определяет фрагмент текста двунаправленного форматирования, который должен быть изолирован от остального текста.</p>\r\n  <p>Элемент <strong>&lt;figcaption&gt;</strong> используется для добавления подписи или пояснений к содержимому тега &lt;figure&gt;.</p>\r\n  <p>Элемент <strong>&lt;figure&gt;</strong> определяет автономный контент, являющийся самостоятельным элементом основного потока. Используется для добавления кратких аннотаций к иллюстрациям, фотографиям, диаграммам, фрагментам кода и т.д.</p>\r\n  <p>Элемент <strong>&lt;footer&gt;</strong> формирует нижний колонтитул секции или корневого элемента, в котором находится. Как правило, в нем размещается информация об авторских правах, контактные данные, ссылки для навигации и т.д.</p>\r\n  <p>Элемент <strong>&lt;main&gt;</strong> формирует основное содержимое документа (содержимое элемента &lt;body&gt;). Содержимое тега должно быть уникальным и не дублировать однотипные блоки, которые повторяются в других документах, таких как шапка сайта (header), нижний колонтитул (footer), меню, форма поиска, информация об авторских правах и т.д.</p>\r\n  <p>Элемент <strong>&lt;mark&gt;</strong> используется для выделения важного содержимого или ключевых слов. По умолчанию выделяет желтым цветом.</p>\r\n  <p>Элемент <strong>&lt;nav&gt;</strong> формирует основной блок навигационных ссылок. Обратите внимание, что не все ссылки в HTML документе могут быть помещены внутрь элемента &lt;nav&gt;, он может включать в себя только крупные навигационные блоки.</p>\r\n  <p>Элемент <strong>&lt;section&gt;</strong> используется для группировки тематического содержимого (оглавление, программа, разделы и т.д.).</p>\r\n  <p>Элемент <strong>&lt;time&gt;</strong> определяет время (24 часа) или дату по григорианскому календарю с возможным указанием времени и смещения часового пояса.</p>\r\n  <p>Элемент <strong>&lt;wbr&gt;</strong> указывает браузеру место возможного разрыва длинной строки в случае необходимости.</p>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"html5\"></div>\r\n  <h2>Элементы, которые появились в стандарте HTML5 (30)</h2>\r\n  <p>\r\n    <strong>&lt;article&gt;</strong>\r\n    <strong>&lt;aside&gt;</strong>\r\n    <strong>&lt;audio&gt;</strong>\r\n    <strong>&lt;bdi&gt;</strong>\r\n    <strong>&lt;canvas&gt;</strong>\r\n    <strong>&lt;command&gt;</strong>\r\n    <strong>&lt;datalist&gt;</strong>\r\n    <strong>&lt;details&gt;</strong>\r\n    <strong>&lt;figcaption&gt;</strong>\r\n    <strong>&lt;figure&gt;</strong>\r\n    <strong>&lt;footer&gt;</strong>\r\n    <strong>&lt;header&gt;</strong>\r\n    <strong>&lt;hgroup&gt;</strong>\r\n    <strong>&lt;keygen&gt;</strong>\r\n    <strong>&lt;main&gt;</strong>\r\n    <strong>&lt;mark&gt;</strong>\r\n    <strong>&lt;menu&gt;</strong>\r\n    <strong>&lt;meter&gt;</strong>\r\n    <strong>&lt;nav&gt;</strong>\r\n    <strong>&lt;output&gt;</strong>\r\n    <strong>&lt;progress&gt;</strong>\r\n    <strong>&lt;rp&gt;</strong>\r\n    <strong>&lt;rt&gt;</strong>\r\n    <strong>&lt;ruby&gt;</strong>\r\n    <strong>&lt;section&gt;</strong>\r\n    <strong>&lt;source&gt;</strong>\r\n    <strong>&lt;summary&gt;</strong>\r\n    <strong>&lt;time&gt;</strong>\r\n    <strong>&lt;video&gt;</strong>\r\n    <strong>&lt;wbr&gt;</strong>\r\n  </p>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"block\"></div>\r\n  <h2>Block elements (Блочные элементы) (20)</h2>\r\n  <p>\r\n    <strong>&lt;address&gt;</strong>\r\n    <strong>&lt;blockquote&gt;</strong>\r\n    <strong>&lt;center&gt;</strong>\r\n    <strong>&lt;div&gt;</strong>\r\n    <strong>&lt;fieldset&gt;</strong>\r\n    <strong>&lt;form&gt;</strong>\r\n    <strong>&lt;h1&gt;</strong>\r\n    <strong>&lt;h2&gt;</strong>\r\n    <strong>&lt;h3&gt;</strong>\r\n    <strong>&lt;h4&gt;</strong>\r\n    <strong>&lt;h5&gt;</strong>\r\n    <strong>&lt;h6&gt;</strong>\r\n    <strong>&lt;hr&gt;</strong>\r\n    <strong>&lt;isindex&gt;</strong>\r\n    <strong>&lt;menu&gt;</strong>\r\n    <strong>&lt;ol&gt;</strong>\r\n    <strong>&lt;p&gt;</strong>\r\n    <strong>&lt;pre&gt;</strong>\r\n    <strong>&lt;table&gt;</strong>\r\n    <strong>&lt;ul&gt;</strong>\r\n  </p>\r\n  <p>Блочные элементы занимают всю доступную ширину, высота элемента определяется его содержимым, и он всегда начинается с новой строки.</p>\r\n  <p>Тег <strong>&lt;address&gt;</strong> предназначен для хранения информации об авторе</p>\r\n  <p>Тег <strong>&lt;blockquote&gt;</strong> Предназначен для выделения длинных цитат внутри документа.</p>\r\n  <p>Тег <strong>&lt;center&gt;</strong> Выравнивает содержимое контейнера по центру относительно родительского элемента.</p>\r\n  <p>Тег <strong>&lt;div&gt;</strong> Универсальный блочный элемент.</p>\r\n  <p>Тег <strong>&lt;fieldset&gt;</strong> Предназначен для группирования элементов формы.</p>\r\n  <p>Тег <strong>&lt;form&gt;</strong> Устанавливает форму на веб-странице.</p>\r\n  <p>Тег <strong>&lt;h1&gt;</strong> Заголовок первого уровня.</p>\r\n  <p>Тег <strong>&lt;h2&gt;</strong> Заголовок второго уровня.</p>\r\n  <p>Тег <strong>&lt;h3&gt;</strong> заголовок третьего уровня.</p>\r\n  <p>Тег <strong>&lt;h4&gt;</strong> заголовок четвертого уровня.</p>\r\n  <p>Тег <strong>&lt;h5&gt;</strong> заголовок пятого уровня.</p>\r\n  <p>Тег <strong>&lt;h6&gt;</strong> заголовок шестого уровня.</p>\r\n  <p>Тег <strong>&lt;hr&gt;</strong> горизонтальная линия.</p>\r\n  <p>Тег <strong>&lt;isindex&gt;</strong> Используется для поискового индекса в текущем документе.</p>\r\n  <p>Тег <strong>&lt;menu&gt;</strong> Отображает список меню.</p>\r\n  <p>Тег <strong>&lt;ol&gt;</strong> нумерованный список.</p>\r\n  <p>Тег <strong>&lt;p&gt;</strong> текстовый абзац.</p>\r\n  <p>Тег <strong>&lt;pre&gt;</strong> Определяет блок предварительно форматированного текста.</p>\r\n  <p>Тег <strong>&lt;table&gt;</strong> Создает таблицу.</p>\r\n  <p>Тег <strong>&lt;ul&gt;</strong> маркированный список.</p>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"inline\"></div>\r\n  <h2>Inline elements (Строчные элементы) (32)</h2>\r\n  <p>\r\n    <strong>&lt;a&gt;</strong>\r\n    <strong>&lt;abbr&gt;</strong>\r\n    <strong>&lt;acronym&gt;</strong>\r\n    <strong>&lt;b&gt;</strong>\r\n    <strong>&lt;basefont&gt;</strong>\r\n    <strong>&lt;bdo&gt;</strong>\r\n    <strong>&lt;big&gt;</strong>\r\n    <strong>&lt;br&gt;</strong>\r\n    <strong>&lt;cite&gt;</strong>\r\n    <strong>&lt;code&gt;</strong>\r\n    <strong>&lt;dfn&gt;</strong>\r\n    <strong>&lt;em&gt;</strong>\r\n    <strong>&lt;font&gt;</strong>\r\n    <strong>&lt;i&gt;</strong>\r\n    <strong>&lt;img&gt;</strong>\r\n    <strong>&lt;input&gt;</strong>\r\n    <strong>&lt;kbd&gt;</strong>\r\n    <strong>&lt;label&gt;</strong>\r\n    <strong>&lt;q&gt;</strong>\r\n    <strong>&lt;s&gt;</strong>\r\n    <strong>&lt;samp&gt;</strong>\r\n    <strong>&lt;select&gt;</strong>\r\n    <strong>&lt;small&gt;</strong>\r\n    <strong>&lt;strike&gt;</strong>\r\n    <strong>&lt;strong&gt;</strong>\r\n    <strong>&lt;span&gt;</strong>\r\n    <strong>&lt;sub&gt;</strong>\r\n    <strong>&lt;sup&gt;</strong>\r\n    <strong>&lt;textarea&gt;</strong>\r\n    <strong>&lt;tt&gt;</strong>\r\n    <strong>&lt;u&gt;</strong>\r\n    <strong>&lt;var&gt;</strong>\r\n  </p>\r\n  <p>Строчные элементы являются частью другого элемента, например, текстового абзаца. В основном они используются для изменения вида текста или его логического выделения.</p>\r\n  <p>Тег <strong>&lt;a&gt;</strong> Является одним из важных элементов HTML и предназначен для создания ссылок.</p>\r\n  <p>Тег <strong>&lt;abbr&gt;</strong> указывает, что последовательность символов является аббревиатурой.</p>\r\n  <p>Тег <strong>&lt;acronym&gt;</strong> Сообщает, что текст является акронимом. В отличие от аббревиатуры, акроним — это устоявшееся сокращение, которое применяется как самостоятельное слово.</p>\r\n  <p>Тег <strong>&lt;b&gt;</strong> Устанавливает жирное начертание шрифта</p>\r\n  <p>Тег <strong>&lt;basefont&gt;</strong> Предназначен для задания шрифта, размера и цвета текста по умолчанию.</p>\r\n  <p>Тег <strong>&lt;bdo&gt;</strong> Устанавливает направление вывода текста: слева направо или справа налево.</p>\r\n  <p>Тег <strong>&lt;big&gt;</strong> Увеличивает размер шрифта на единицу по сравнению с обычным текстом.</p>\r\n  <p>Тег <strong>&lt;br&gt;</strong> Перенос строки.</p>\r\n  <p>Тег <strong>&lt;cite&gt;</strong> Помечает текст как цитату или сноску на другой материал.</p>\r\n  <p>Тег <strong>&lt;code&gt;</strong> Предназначен для отображения текста программного кода.</p>\r\n  <p>Тег <strong>&lt;dfn&gt;</strong> Выделяет термин в документе.</p>\r\n  <p>Тег <strong>&lt;em&gt;</strong> Предназначен для акцентирования текста.</p>\r\n  <p>Тег <strong>&lt;font&gt;</strong> Предназначен для изменения характеристик шрифта, таких как размер, цвет и гарнитура.</p>\r\n  <p>Тег <strong>&lt;i&gt;</strong> Устанавливает курсивное начертание шрифта.</p>\r\n  <p>Тег <strong>&lt;img&gt;</strong> Устанавливает изображение.</p>\r\n  <p>Тег <strong>&lt;input&gt;</strong> Позволяет создавать разные элементы интерфейса.</p>\r\n  <p>Тег <strong>&lt;kbd&gt;</strong> Используется для обозначения текста, который набирается на клавиатуре или для названия клавиш.</p>\r\n  <p>Тег <strong>&lt;label&gt;</strong> Устанавливает связь между определенной меткой и элементом формы.</p>\r\n  <p>Тег <strong>&lt;q&gt;</strong> Используется для выделения в тексте цитат.</p>\r\n  <p>Тег <strong>&lt;s&gt;</strong> Отображает текст как перечеркнутый.</p>\r\n  <p>Тег <strong>&lt;samp&gt;</strong> Используется для отображения текста, который является результатом вывода компьютерной программы.</p>\r\n  <p>Тег <strong>&lt;select&gt;</strong> Создает раскрывающийся список.</p>\r\n  <p>Тег <strong>&lt;small&gt;</strong> Уменьшает размер шрифта на единицу по сравнению с обычным текстом.</p>\r\n  <p>Тег <strong>&lt;span&gt;</strong> Универсальный       строчный элемент.</p>\r\n  <p>Тег <strong>&lt;strike&gt;</strong> Отображает текст как перечеркнутый.</p>\r\n  <p>Тег <strong>&lt;strong&gt;</strong> Акцентирует текст, обычно жирным начертанием.</p>\r\n  <p>Тег <strong>&lt;sub&gt;</strong>\r\n  Отображает шрифт в виде нижнего индекса.</p>\r\n  <p>Тег <strong>&lt;sup&gt;</strong> Отображает шрифт в виде верхнего индекса.</p>\r\n  <p>Тег <strong>&lt;textarea&gt;</strong> Создает поле для многострочного текста.</p>\r\n  <p>Тег <strong>&lt;tt&gt;</strong> Отображает текст моноширинным текстом.</p>\r\n  <p>Тег <strong>&lt;u&gt;</strong> Добавляет подчеркивание к тексту.</p>\r\n  <p>Тег <strong>&lt;var&gt;</strong> Используется для выделения переменных компьютерных программ.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"no-standard\"></div>\r\n  <h2>Нестандартные теги (9)</h2>\r\n  <p>\r\n    <strong>&lt;bgsound&gt;</strong>\r\n    <strong>&lt;blink&gt;</strong>\r\n    <strong>&lt;comment&gt;</strong>\r\n    <strong>&lt;marquee&gt;</strong>\r\n    <strong>&lt;multicol&gt;</strong>\r\n    <strong>&lt;nobr&gt;</strong>\r\n    <strong>&lt;noembed&gt;</strong>\r\n    <strong>&lt;plaintext&gt;</strong>\r\n    <strong>&lt;spacer&gt;</strong>\r\n  </p>\r\n  <p>Некоторые разработчики браузеров или поисковых систем включают поддержку собственных тегов, которые не входят в спецификацию HTML. Использование этих тегов приводит к невалидному коду, а также поддерживаются не всеми браузерами.</p>\r\n  <p>Тег <strong>&lt;bgsound&gt;</strong> Определяет музыкальный файл, который будет проигрываться на веб-странице.</p>\r\n  <p>Тег <strong>&lt;blink&gt;</strong> Устанавливает мигание текста.</p>\r\n  <p>Тег <strong>&lt;comment&gt;</strong> Добавляет комментарий в код документа.</p>\r\n  <p>Тег <strong>&lt;marquee&gt;</strong> Создает бегущую строку на странице.</p>\r\n  <p>Тег <strong>&lt;multicol&gt;</strong> Задает количество колонок, ширину и расстояние между колонками в многоколоночном тексте.</p>\r\n  <p>Тег <strong>&lt;nobr&gt;</strong> Уведомляет браузер отображать текст без переносов.</p>\r\n  <p>Тег <strong>&lt;noembed&gt;</strong> предназначен для отображения информации на веб-странице, если браузер не поддерживает работу с плагинами.</p>\r\n  <p>Тег <strong>&lt;plaintext&gt;</strong> Отображает содержимое контейнера «как есть».</p>\r\n  <p>Тег <strong>&lt;spacer&gt;</strong> Создает пустое пространство по вертикали или горизонтали.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"doctype\"></div>\r\n  <h2>Тип документа &lt;!DOCTYPE&gt;</h2>\r\n\r\n  <p>Пишется первой строчкой любого html документа. Для страниц стандарта html5 имеет вид\r\n  <code>&lt;!DOCTYPE html&gt;</code></p>\r\n\r\n  <p>Элемент &lt;!DOCTYPE&gt; предназначен для указания типа текущего документа — DTD (document type definition, описание типа документа). Это необходимо, чтобы браузер понимал, как следует интерпретировать текущую веб-страницу. Поскольку HTML существует в нескольких версиях, существует несколько видов &lt;!DOCTYPE&gt;</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"comment\"></div>\r\n  <h2>Комментарий &lt;!--...--&gt;</h2>\r\n\r\n  <p>Браузер игнорирует все что написано внутри. Таким образом можно оставлять комментарий к коду или экранировать фрагменты кода. Вложенные комментарии (один комментарий в другом) не поддерживаются.\r\n  <code>&lt;!-- какой-то комментарий к коду --&gt;</code></p>\r\n\r\n\r\n  <p>Если комментарий расположен внутри тега &lt;title&gt;, он трактуется как текст и будет показан в заголовке страницы. Проще говоря, тег &lt;!-- --&gt; внутри тега &lt;title&gt; не работает.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-html\"></div>\r\n  <h2>Root Element (Корневой элемент) &lt;html&gt;</h2>\r\n\r\n  <p>В документе html может быть только один корневой элемент &lt;html&gt;. Он идет сразу после элемента &lt;doctype&gt;\r\n  <code>&lt;!DOCTYPE html&gt;\r\n  <br>&lt;html&gt;&lt;/html&gt;</code></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"base-elements\"></div>\r\n  <h2>Базовые элементы (2)</h2>\r\n  <p><a href=\"#tag-head\">&lt;head&gt;</a>\r\n  <a href=\"#tag-body\">&lt;body&gt;</a></p>\r\n\r\n  <p>В корневой элемент &lt;html&gt; последовательно вкладывают базовые элементы &lt;head&gt; и &lt;body&gt;\r\n\r\n  <code>&lt;!DOCTYPE html&gt;\r\n  <br>&lt;html&gt;\r\n  <br>&nbsp;&nbsp;&lt;head&gt;\r\n  <br>&nbsp;&nbsp;&lt;/head&gt;\r\n  <br>&nbsp;&nbsp;&lt;body&gt;\r\n  <br>&nbsp;&nbsp;&lt;/body&gt;\r\n  <br>&lt;/html&gt;</code></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-head\"></div>\r\n  <h3>&lt;head&gt;</h3>\r\n\r\n  <p>Содержимое тега &lt;head&gt; не отображается напрямую на веб-странице, за исключением тега &lt;title&gt; устанавливающего заголовок окна веб-страницы. Внутри контейнера &lt;head&gt;  находятся метатеги, которые используются для хранения информации предназначенной для браузеров и поисковых систем. Внутри контейнера &lt;head&gt; допускается размещать следующие элементы: &lt;base&gt;, &lt;link&gt;, &lt;meta&gt;, &lt;script&gt;, &lt;style&gt;, &lt;title&gt; (устаревшие &lt;basefont&gt;, &lt;bgsound&gt;).</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-body\"></div>\r\n  <h3>&lt;body&gt;</h3>\r\n  <p>В теге &lt;body&gt; находится все содержимое страницы, которое показывается в окне браузера.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"metadata\"></div>\r\n  <h2>Document Metadata (Метаданные) (5)</h2>\r\n  <p><a href=\"#tag-meta\">&lt;meta /&gt;</a>\r\n  <a href=\"#tag-base\">&lt;base /&gt;</a>\r\n  <a href=\"#tag-link\">&lt;link /&gt;</a>\r\n  <a href=\"#tag-title\">&lt;title&gt;</a>\r\n  <a href=\"#tag-style\">&lt;style&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-meta\"></div>\r\n  <h3>&lt;meta /&gt;</h3>\r\n  <p>Всегда внутри контейнера &lt;head&gt;. Данные в нем не видны пользователю и предназначены для браузеров и поисковых систем.\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-base\"></div>\r\n  <h3>&lt;base /&gt;</h3>\r\n  <p>Всегда внутри контейнера &lt;head&gt;. Сообщает браузеру полный базовый адрес текущего документа. В атрибут href пишут адрес, который должен использоваться для указания полного пути к файлам. &lt;base /&gt; предназначен для документов, в которых используется относительный адрес и эти документы могут переноситься в другую папку или даже на другой компьютер без потери связи.</p>\r\n  <p>Второе применение элемента <base> — задание целевого окна для всех ссылок на текущей странице. В атрибут target пишут имя окна, в котором будут открываться все ссылки.</p>\r\n  <p>Если на странице встречается несколько элементов <base>, то берётся значение атрибутов только у первого элемента, остальные игнорируются.</p>\r\n\r\n  <code>&lt;!DOCTYPE html&gt;\r\n  <br>&lt;html&gt;\r\n  <br>&nbsp;&nbsp;&lt;head&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;base href=\"https://html5css.ru/images/\" target=\"_blank\"&gt;\r\n  <br>&nbsp;&nbsp;&lt;/head&gt;\r\n  <br>&nbsp;&nbsp;&lt;body&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;img src=\"spiderman.gif\" width=\"50\" height=\"100\" alt=\"Spiderman\"&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;a href=\"spiderman.html\"&gt;Человек-паук&lt;/a&gt;\r\n  <br>&nbsp;&nbsp;&lt;/body&gt;\r\n  <br>&lt;/html&gt;</code>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-link\"></div>\r\n  <h3>&lt;link /&gt;</h3>\r\n  <p>Всегда внутри контейнера &lt;head&gt;. Устанавливает связь с внешним документом вроде файла со стилями, со шрифтами или favicon.</p>\r\n\r\n  <code>&lt;!DOCTYPE html&gt;\r\n  <br>&lt;html&gt;\r\n  <br>&nbsp;&nbsp;&lt;head&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;link rel=\"preload\" href=\"https://htmlacademy.ru/fonts/roboto.woff2\" as=\"font\"\"&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;link rel=\"stylesheet\" href=\"style.css\"&gt;\r\n  <br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;link rel=\"icon\" href=\"favicon.ico\"&gt;\r\n  <br>&nbsp;&nbsp;&lt;/head&gt;\r\n  <br>&nbsp;&nbsp;&lt;body&gt;\r\n  <br>&nbsp;&nbsp;&lt;/body&gt;\r\n  <br>&lt;/html&gt;</code>\r\n\r\n  <p>Чтобы сделать предзагрузку шрифта на страницу, нужно в теге &lt;head&gt; разместить тег &lt;link /&gt;, в аттрибуте rel прописать значение preload, в аттрибуте href прописать адрес шрифта, в аттрибуте as прописать тип ресурса, в данном случае font.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-title\"></div>\r\n  <h3>&lt;title&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-style\"></div>\r\n  <h3>&lt;style&gt;</h3>\r\n</article>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"section-elements\"></div>\r\n  <h2>Sections (Секции) (8)</h2>\r\n  <p><a href=\"#tag-header\">&lt;header&gt;</a>\r\n  <a href=\"#tag-nav\">&lt;nav&gt;</a>\r\n  <a href=\"#tag-aside\">&lt;aside&gt;</a>\r\n  <a href=\"#tag-main\">&lt;main&gt;</a>\r\n  <a href=\"#tag-article\">&lt;article&gt;</a>\r\n  <a href=\"#tag-section\">&lt;section&gt;</a>\r\n  <a href=\"#tag-adress\">&lt;adress&gt;</a>\r\n  <a href=\"#tag-footer\">&lt;footer&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-header\"></div>\r\n  <h3>&lt;header&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-nav\"></div>\r\n  <h3>&lt;nav&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-aside\"></div>\r\n  <h3>&lt;aside&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-main\"></div>\r\n  <h3>&lt;main&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-article\"></div>\r\n  <h3>&lt;article&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-section\"></div>\r\n  <h3>&lt;section&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-adress\"></div>\r\n  <h3>&lt;adress&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-footer\"></div>\r\n  <h3>&lt;footer&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"container-elements\"></div>\r\n  <h2>Container (Контейнер) (2)</h2>\r\n  <p><a href=\"#tag-div\">&lt;div&gt;</a>\r\n  <a href=\"#tag-span\">&lt;span&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-div\"></div>\r\n  <h3>&lt;div&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-span\"></div>\r\n  <h3>&lt;span&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"headings\"></div>\r\n  <h2>Headings (Заголовки) (7)</h2>\r\n  <p><a href=\"#tag-hgroup\">&lt;hgroup&gt;</a>\r\n  <a href=\"#tag-h1\">&lt;h1&gt;</a>\r\n  <a href=\"#tag-h2\">&lt;h2&gt; - &lt;h6&gt;</a></p>\r\n\r\n  <p>HTML предлагает шесть заголовков разного уровня, которые показывают относительную важность секции, расположенной после заголовка. &lt;h1&gt; представляет собой наиболее важный заголовок первого уровня. Считается что он должен быть один на странице. Отображается самым крупным шрифтом жирного начертания, заголовки последующего уровня по размеру меньше. Это блочные элементы. Перед заголовком и после него добавляется пустое пространство.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-hgroup\"></div>\r\n  <h3>&lt;hgroup&gt;</h3>\r\n\r\n  <p>Представляет заголовок раздела. Группирует несколько заголовков. Связывает вторичный заголовок или даже теги с основным заголовком без загрязнения структуры документа</p>\r\n  <code>\r\n    &lt;hgroup&gt;<br>\r\n      &nbsp;&nbsp;&lt;h1&gt;Главный заголовок&lt;/h1&gt;<br>\r\n      &nbsp;&nbsp;&lt;h2&gt;Вторичный заголовок&lt;/h2&gt;<br>\r\n    &lt;/hgroup&gt;\r\n  </code>\r\n  <code>\r\n    &lt;hgroup id=\"document-title\"&gt;<br>\r\n      &nbsp;&nbsp;&lt;h1&gt;HTML: Living Standard&lt;/h1&gt;<br>\r\n      &nbsp;&nbsp;&lt;p&gt;Last Updated 12 July 2022&lt;/p&gt;<br>\r\n    &lt;/hgroup&gt;\r\n  </code>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-h1\"></div>\r\n  <h3>&lt;h1&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-h2\"></div>\r\n  <h3>&lt;h2&gt; &lt;h3&gt; &lt;h4&gt; &lt;h5&gt; &lt;h6&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements1\"></div>\r\n  <h2>Оформление текста (6)</h2>\r\n  <p><a href=\"#tag-a\">&lt;a&gt;</a>\r\n  <a href=\"#tag-hr\">&lt;hr /&gt;</a>\r\n  <a href=\"#tag-p\">&lt;p&gt;</a>\r\n  <a href=\"#tag-pre\">&lt;pre&gt;</a>\r\n  <a href=\"#tag-br\">&lt;br /&gt;</a>\r\n  <a href=\"#tag-wbr\">&lt;wbr /&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-a\"></div>\r\n  <h3>Гиперссылка &lt;a&gt;</h3>\r\n  <p>Тег a создает ссылку на другую страницу своего или чужого сайта. Адрес ссылки следует писать в атрибуте href. Ссылки по умолчанию подчеркнуты. Отменить подчеркивание можно с помощью CSS свойства text-decoration.</p>\r\n  <p>Атрибуты</p>\r\n  <p><strong>href</strong> Адрес страницы, на которую ссылается ссылка</p>\r\n  <p><strong>target</strong> Указывает ссылке в какой вкладке ей открываться</p>\r\n  <p>Значения атрибута <strong>target</strong> (Значение по умолчанию: <strong>_self</strong>)</p>\r\n  <p><strong>_blank</strong> Страница откроется в <strong>новой</strong> вкладке браузера.</p>\r\n  <p><strong>_self</strong>\tСтраница откроется в <strong>текущей</strong> вкладке браузера.</p>\r\n  <p><strong>_parent</strong>\tСтраница откроется во <strong>фрейме-родителе.</strong></p>\r\n  <p><strong>_top</strong> Отменяет все фреймы и загружает страницу в полном окне браузера.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-hr\"></div>\r\n  <h3>Горизонтальная линия &lt;hr /&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-p\"></div>\r\n  <h3>Параграф &lt;p&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-pre\"></div>\r\n  <h3>&lt;pre&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-br\"></div>\r\n  <h3>Конец строки &lt;br /&gt;</h3>\r\n  <p>(от англ. line break — перенос строки)</p>\r\n  <code>У лукоморья дуб зелёный;&lt;br&gt;\r\n  <br>Златая цепь на дубе том</code>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-wbr\"></div>\r\n  <h3>Мягкий перенос строки &lt;wbr /&gt;</h3>\r\n  <p>Указывает браузеру, что в этом месте можно сделать перенос строки</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements2\"></div>\r\n  <h2>Выделение текста (10)</h2>\r\n  <p><a href=\"#tag-b\">&lt;b&gt;</a>\r\n  <a href=\"#tag-i\">&lt;i&gt;</a>\r\n  <a href=\"#tag-s\">&lt;s&gt;</a>\r\n  <a href=\"#tag-u\">&lt;u&gt;</a>\r\n  <a href=\"#tag-del\">&lt;del&gt;</a>\r\n  <a href=\"#tag-ins\">&lt;ins&gt;</a>\r\n  <a href=\"#tag-mark\">&lt;mark&gt;</a>\r\n  <a href=\"#tag-small\">&lt;small&gt;</a>\r\n  <a href=\"#tag-sup\">&lt;sup&gt;</a>\r\n  <a href=\"#tag-sub\">&lt;sub&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-b\"></div>\r\n  <h3>&lt;b&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-i\"></div>\r\n  <h3>&lt;i&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-s\"></div>\r\n  <h3>&lt;s&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-u\"></div>\r\n  <h3>&lt;u&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-del\"></div>\r\n  <h3>&lt;del&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-ins\"></div>\r\n  <h3>&lt;ins&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-mark\"></div>\r\n  <h3>&lt;mark&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-small\"></div>\r\n  <h3>&lt;small&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-sup\"></div>\r\n  <h3>&lt;sup&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-sub\"></div>\r\n  <h3>&lt;sub&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements3\"></div>\r\n  <h2>Значение текста (10)</h2>\r\n  <p><a href=\"#tag-abbr\">&lt;abbr&gt;</a>\r\n  <a href=\"#tag-code\">&lt;code&gt;</a>\r\n  <a href=\"#tag-data\">&lt;data&gt;</a>\r\n  <a href=\"#tag-dfn\">&lt;dfn&gt;</a>\r\n  <a href=\"#tag-em\">&lt;em&gt;</a>\r\n  <a href=\"#tag-kbd\">&lt;kbd&gt;</a>\r\n  <a href=\"#tag-samp\">&lt;samp&gt;</a>\r\n  <a href=\"#tag-strong\">&lt;strong&gt;</a>\r\n  <a href=\"#tag-time\">&lt;time&gt;</a>\r\n  <a href=\"#tag-var\">&lt;var&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-abbr\"></div>\r\n  <h3>&lt;abbr&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-code\"></div>\r\n  <h3>&lt;code&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-data\"></div>\r\n  <h3>&lt;data&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dfn\"></div>\r\n  <h3>&lt;dfn&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-em\"></div>\r\n  <h3>&lt;em&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-kbd\"></div>\r\n  <h3>&lt;kbd&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-samp\"></div>\r\n  <h3>&lt;samp&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-strong\"></div>\r\n  <h3>&lt;strong&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-time\"></div>\r\n  <h3>&lt;time&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-var\"></div>\r\n  <h3>&lt;var&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements4\"></div>\r\n  <h2>Цитаты (3)</h2>\r\n  <p><a href=\"#tag-blockquote\">&lt;blockquote&gt;</a>\r\n  <a href=\"#tag-q\">&lt;q&gt;</a>\r\n  <a href=\"#tag-cite\">&lt;cite&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-blockquote\"></div>\r\n  <h3>&lt;blockquote&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-q\"></div>\r\n  <h3>&lt;q&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-cite\"></div>\r\n  <h3>&lt;cite&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements5\"></div>\r\n  <h2>Направление текста (2)</h2>\r\n  <p><a href=\"#tag-bdi\">&lt;bdi&gt;</a>\r\n  <a href=\"#tag-tbdo\">&lt;tbdo&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-bdi\"></div>\r\n  <h3>&lt;bdi&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-tbdo\"></div>\r\n  <h3>&lt;tbdo&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"text-elements6\"></div>\r\n  <h2>Аннотация к иероглифам (3)</h2>\r\n  <p><a href=\"#tag-ruby\">&lt;ruby&gt;</a>\r\n  <a href=\"#tag-rt\">&lt;rt&gt;</a>\r\n  <a href=\"#tag-rp\">&lt;rp&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-ruby\"></div>\r\n  <h3>&lt;ruby&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-rt\"></div>\r\n  <h3>&lt;rt&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-rp\"></div>\r\n  <h3>&lt;rp&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"list-elements\"></div>\r\n  <h2>List (Список) (8)</h2>\r\n  <p><a href=\"#tag-ol\">&lt;ol&gt;</a>\r\n  <a href=\"#tag-ul\">&lt;ul&gt;</a>\r\n  <a href=\"#tag-li\">&lt;li&gt;</a>\r\n  <a href=\"#tag-dl\">&lt;dl&gt;</a>\r\n  <a href=\"#tag-dt\">&lt;dt&gt;</a>\r\n  <a href=\"#tag-dd\">&lt;dd&gt;</a>\r\n  <a href=\"#tag-menu\">&lt;menu&gt;</a>\r\n  <a href=\"#tag-command\">&lt;command&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-ol\"></div>\r\n  <h3>&lt;ol&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-ul\"></div>\r\n  <h3>&lt;ul&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-li\"></div>\r\n  <h3>&lt;li&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dl\"></div>\r\n  <h3>&lt;dl&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dt\"></div>\r\n  <h3>&lt;dt&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dd\"></div>\r\n  <h3>&lt;dd&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-menu\"></div>\r\n  <h3>&lt;menu&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-command\"></div>\r\n  <h3>&lt;command&gt;</h3>\r\n  <div><a href=\"#page\">Содержание</a></div>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"table-elements\"></div>\r\n  <h2>Table (Таблица) (10)</h2>\r\n  <p><a href=\"#tag-table\">&lt;table&gt;</a>\r\n  <a href=\"#tag-caption\">&lt;caption&gt;</a>\r\n  <a href=\"#tag-colgroup\">&lt;colgroup&gt;</a>\r\n  <a href=\"#tag-col\">&lt;col&gt;</a>\r\n  <a href=\"#tag-thead\">&lt;thead&gt;</a>\r\n  <a href=\"#tag-tfoot\">&lt;tfoot&gt;</a>\r\n  <a href=\"#tag-tbody\">&lt;tbody&gt;</a>\r\n  <a href=\"#tag-tr\">&lt;tr&gt;</a>\r\n  <a href=\"#tag-th\">&lt;th&gt;</a>\r\n  <a href=\"#tag-td\">&lt;td&gt;</a></p>\r\n\r\n  <table class=\"table\">\r\n  <caption>Таблица рекордов</caption>\r\n  <colgroup>\r\n  <col class=\"col-1\">\r\n  <col class=\"col-2\">\r\n  <col class=\"col-3\">\r\n  </colgroup>\r\n  <thead>\r\n  <tr>\r\n  <th>Место</th>\r\n  <th>Счет</th>\r\n  <th>Игрок</th>\r\n  </tr>\r\n  </thead>\r\n  <tfoot>\r\n  <tr>\r\n  <th>Текущий счет</th>\r\n  <th colspan=\"2\">25</th>\r\n  </tr>\r\n  </tfoot>\r\n  <tbody>\r\n  <tr>\r\n  <td>1</td>\r\n  <td>21</td>\r\n  <td rowspan=\"2\">Вова</td>\r\n  </tr>\r\n  <tr>\r\n  <td>2</td>\r\n  <td>20</td>\r\n  </tr>\r\n  <tr>\r\n  <td>3</td>\r\n  <td>15</td>\r\n  <td>Маша</td>\r\n  </tr>\r\n  <tr>\r\n  <td>4</td>\r\n  <td>10</td>\r\n  <td>Варя</td>\r\n  </tr>\r\n  </tbody>\r\n  </table>\r\n  <pre>&lt;table&gt;\r\n\r\n&lt;caption&gt;Таблица рекордов&lt;/caption&gt;\r\n\r\n&lt;colgroup&gt;\r\n&lt;col class=\"col-1\"&gt;\r\n&lt;col class=\"col-2\"&gt;\r\n&lt;col class=\"col-3\"&gt;\r\n&lt;/colgroup&gt;\r\n\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;Место&lt;/th&gt;\r\n&lt;th&gt;Счет&lt;/th&gt;\r\n&lt;th&gt;Игрок&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n\r\n&lt;tfoot&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;Текущий счет&lt;/th&gt;\r\n&lt;th colspan=\"2\"&gt;25&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/tfoot&gt;\r\n\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1&lt;/td&gt;\r\n&lt;td&gt;21&lt;/td&gt;\r\n&lt;td rowspan=\"2\"&gt;Вова&lt;/td&gt;\r\n&lt;/tr&gt;\r\n\r\n&lt;tr&gt;\r\n&lt;td&gt;2&lt;/td&gt;\r\n&lt;td&gt;20&lt;/td&gt;\r\n&lt;/tr&gt;\r\n\r\n&lt;tr&gt;\r\n&lt;td&gt;3&lt;/td&gt;\r\n&lt;td&gt;15&lt;/td&gt;\r\n&lt;td&gt;Маша&lt;/td&gt;\r\n&lt;/tr&gt;\r\n\r\n&lt;tr&gt;\r\n&lt;td&gt;4&lt;/td&gt;\r\n&lt;td&gt;10&lt;/td&gt;\r\n&lt;td&gt;Варя&lt;/td&gt;\r\n&lt;/tr&gt;\r\n\r\n&lt;/tbody&gt;\r\n\r\n&lt;/table&gt;\r\n\r\n</pre>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-table\"></div>\r\n  <h3>&lt;table&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-caption\"></div>\r\n  <h3>&lt;caption&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-colgroup\"></div>\r\n  <h3>&lt;colgroup&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-col\"></div>\r\n  <h3>&lt;col&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-thead\"></div>\r\n  <h3>&lt;thead&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-tfoot\"></div>\r\n  <h3>&lt;tfoot&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-tbody\"></div>\r\n  <h3>&lt;tbody&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-tr\"></div>\r\n  <h3>&lt;tr&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-th\"></div>\r\n  <h3>&lt;th&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-td\"></div>\r\n  <h3>&lt;td&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"form-elements\"></div>\r\n  <h2>Form (Форма) (14)</h2>\r\n  <p><a href=\"#tag-form\">&lt;form&gt;</a>\r\n  <a href=\"#tag-fieldset\">&lt;fieldset&gt;</a>\r\n  <a href=\"#tag-legend\">&lt;legend&gt;</a>\r\n  <a href=\"#tag-input\">&lt;input&gt;</a>\r\n  <a href=\"#tag-datalist\">&lt;datalist&gt;</a>\r\n  <a href=\"#tag-label\">&lt;label&gt;</a>\r\n  <a href=\"#tag-textarea\">&lt;textarea&gt;</a>\r\n  <a href=\"#tag-select\">&lt;select&gt;</a>\r\n  <a href=\"#tag-optgroup\">&lt;optgroup&gt;</a>\r\n  <a href=\"#tag-meter\">&lt;meter&gt;</a>\r\n  <a href=\"#tag-progress\">&lt;progress&gt;</a>\r\n  <a href=\"#tag-button\">&lt;button&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-form\"></div>\r\n  <h3>&lt;form&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-fieldset\"></div>\r\n  <h3>&lt;fieldset&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-legend\"></div>\r\n  <h3>&lt;legend&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-input\"></div>\r\n  <h3>&lt;input&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-datalist\"></div>\r\n  <h3>&lt;datalist&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-label\"></div>\r\n  <h3>&lt;label&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-textarea\"></div>\r\n  <h3>&lt;textarea&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-select\"></div>\r\n  <h3>&lt;select&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-optgroup\"></div>\r\n  <h3>&lt;optgroup&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-meter\"></div>\r\n  <h3>&lt;meter&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-progress\"></div>\r\n  <h3>&lt;progress&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-button\"></div>\r\n  <h3>&lt;button&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"embed-elements\"></div>\r\n  <h2>Embedded content (Встраиваемый контент) (16)</h2>\r\n  <p><a href=\"#tag-img\">&lt;img /&gt;</a>\r\n  <a href=\"#tag-area\">&lt;area /&gt;</a>\r\n  <a href=\"#tag-picture\">&lt;picture&gt;</a>\r\n  <a href=\"#tag-source\">&lt;source&gt;</a>\r\n  <a href=\"#tag-figure\">&lt;figure&gt;</a>\r\n  <a href=\"#tag-figcaption\">&lt;figcaption&gt;</a>\r\n  <a href=\"#tag-iframe\">&lt;iframe&gt;</a>\r\n  <a href=\"#tag-embed\">&lt;embed&gt;</a>\r\n  <a href=\"#tag-object\">&lt;object&gt;</a>\r\n  <a href=\"#tag-param\">&lt;param&gt;</a>\r\n  <a href=\"#tag-video\">&lt;video&gt;</a>\r\n  <a href=\"#tag-audio\">&lt;audio&gt;</a>\r\n  <a href=\"#tag-track\">&lt;track&gt;</a>\r\n  <a href=\"#tag-map\">&lt;map&gt;</a>\r\n  <a href=\"#tag-use\">&lt;use&gt;</a>\r\n  <a href=\"#tag-svg\">&lt;svg&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-img\"></div>\r\n  <h3>&lt;img /&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-area\"></div>\r\n  <h3>&lt;area /&gt;</h3>\r\n  <p>Определяет активную область на изображении и, при желании, связывает её с гипертекстовой ссылкой. Этот элемент используется только внутри элемента &lt;map&gt;.</p>\r\n  <code>&lt;map name=\"planet\"&gt;\r\n  <br>&nbsp;&nbsp;&lt;area shape=\"rect\" coords=\"0,0,50,50\"\r\n        href=\"sun.html\" alt=\"sun\"&gt;\r\n  <br>&lt;/map&gt;\r\n  <br>&lt;img usemap=\"#planet\" src=\"space.png\" alt=\"space\"&gt;\r\n  </code>\r\n\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-picture\"></div>\r\n  <h3>&lt;picture&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-source\"></div>\r\n  <h3>&lt;source&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-figure\"></div>\r\n  <h3>&lt;figure&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-figcaption\"></div>\r\n  <h3>&lt;figcaption&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-iframe\"></div>\r\n  <h3>&lt;iframe&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-embed\"></div>\r\n  <h3>&lt;embed&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-object\"></div>\r\n  <h3>&lt;object&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-param\"></div>\r\n  <h3>&lt;param&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-video\"></div>\r\n  <h3>&lt;video&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-audio\"></div>\r\n  <h3>&lt;audio&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-track\"></div>\r\n  <h3>&lt;track&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-map\"></div>\r\n  <h3>&lt;map&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-use\"></div>\r\n  <h3>&lt;use&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-svg\"></div>\r\n  <h3>&lt;svg&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"interactive-elements\"></div>\r\n  <h2>Interactive elements (Интерактивные элементы) (3)</h2>\r\n  <p><a href=\"#tag-dialog\">&lt;dialog&gt;</a>\r\n  <a href=\"#tag-details\">&lt;details&gt;</a>\r\n  <a href=\"#tag-summary\">&lt;summary&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dialog\"></div>\r\n  <h3>&lt;dialog&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-details\"></div>\r\n  <h3>&lt;details&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-summary\"></div>\r\n  <h3>&lt;summary&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"script-elements\"></div>\r\n  <h2>Scripting (Скрипты) (2)</h2>\r\n  <p><a href=\"#tag-script\">&lt;script&gt;</a>\r\n  <a href=\"#tag-noscript\">&lt;noscript&gt;</a>\r\n  <a href=\"#tag-canvas\">&lt;canvas&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-script\"></div>\r\n  <h3>&lt;script&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-noscript\"></div>\r\n  <h3>&lt;noscript&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-canvas\"></div>\r\n  <h3>&lt;canvas&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"web-elements\"></div>\r\n  <h2>Web components (Веб-компоненты) (2)</h2>\r\n  <p><a href=\"#tag-template\">&lt;template&gt;</a>\r\n  <a href=\"#tag-slot\">&lt;slot&gt;</a></p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-template\"></div>\r\n  <h3>&lt;template&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-slot\"></div>\r\n  <h3>&lt;slot&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"obsolete-elements\"></div>\r\n  <h2>Obsolete (Устаревшие) (26)</h2>\r\n  <p><a href=\"#tag-acronym\">&lt;acronym&gt;</a>\r\n  <a href=\"#tag-applet\">&lt;applet&gt;</a>\r\n  <a href=\"#tag-basefont\">&lt;basefont&gt;</a>\r\n  <a href=\"#tag-bgsound\">&lt;bgsound&gt;</a>\r\n  <a href=\"#tag-big\">&lt;big&gt;</a>\r\n  <a href=\"#tag-blink\">&lt;blink&gt;</a>\r\n  <a href=\"#tag-center\">&lt;center&gt;</a>\r\n  <a href=\"#tag-content\">&lt;content&gt;</a>\r\n  <a href=\"#tag-dir\">&lt;dir&gt;</a>\r\n  <a href=\"#tag-font\">&lt;font&gt;</a>\r\n  <a href=\"#tag-frame\">&lt;frame&gt;</a>\r\n  <a href=\"#tag-frameset\">&lt;frameset&gt;</a>\r\n  <a href=\"#tag-image\">&lt;image&gt;</a>\r\n  <a href=\"#tag-keygen\">&lt;keygen&gt;</a>\r\n  <a href=\"#tag-marquee\">&lt;marquee&gt;</a>\r\n  <a href=\"#tag-menuitem\">&lt;menuitem&gt;</a>\r\n  <a href=\"#tag-nobr\">&lt;nobr&gt;</a>\r\n  <a href=\"#tag-noembed\">&lt;noembed&gt;</a>\r\n  <a href=\"#tag-noframes\">&lt;noframes&gt;</a>\r\n  <a href=\"#tag-plaintext\">&lt;plaintext&gt;</a>\r\n  <a href=\"#tag-rb\">&lt;rb&gt;</a>\r\n  <a href=\"#tag-rtc\">&lt;rtc&gt;</a>\r\n  <a href=\"#tag-spacer\">&lt;spacer&gt;</a>\r\n  <a href=\"#tag-strike\">&lt;strike&gt;</a>\r\n  <a href=\"#tag-tt\">&lt;tt&gt;</a>\r\n  <a href=\"#tag-xmp\">&lt;xmp&gt;</a></p>\r\n  <p>Осуждаемыми (устаревние) тегаи удалены из спецификации HTML как морально устаревшие. Вместо них рекомендуется использовать другие теги или стили. Хотя браузеры в большинстве случаев прекрасно понимают осуждаемые теги, код с ними проходит валидацию, только при использовании переходного &lt;!DOCTYPE&gt;.</p>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-acronym\"></div>\r\n  <h3>&lt;acronym&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-applet\"></div>\r\n  <h3>&lt;applet&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-basefont\"></div>\r\n  <h3>&lt;basefont&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-bgsound\"></div>\r\n  <h3>&lt;bgsound&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-big\"></div>\r\n  <h3>&lt;big&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-blink\"></div>\r\n  <h3>&lt;blink&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-center\"></div>\r\n  <h3>&lt;center&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-content\"></div>\r\n  <h3>&lt;content&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-dir\"></div>\r\n  <h3>&lt;dir&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-font\"></div>\r\n  <h3>&lt;font&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-frame\"></div>\r\n  <h3>&lt;frame&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-frameset\"></div>\r\n  <h3>&lt;frameset&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-image\"></div>\r\n  <h3>&lt;image&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-keygen\"></div>\r\n  <h3>&lt;keygen&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-marquee\"></div>\r\n  <h3>&lt;marquee&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-menuitem\"></div>\r\n  <h3>&lt;menuitem&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-nobr\"></div>\r\n  <h3>&lt;nobr&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-noembed\"></div>\r\n  <h3>&lt;noembed&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-noframes\"></div>\r\n  <h3>&lt;noframes&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-plaintext\"></div>\r\n  <h3>&lt;plaintext&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-rb\"></div>\r\n  <h3>&lt;rb&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-rtc\"></div>\r\n  <h3>&lt;rtc&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-spacer\"></div>\r\n  <h3>&lt;spacer&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-strike\"></div>\r\n  <h3>&lt;strike&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-tt\"></div>\r\n  <h3>&lt;tt&gt;</h3>\r\n</article>\r\n\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"tag-xmp\"></div>\r\n  <h3>&lt;xmp&gt;</h3>\r\n</article>";
// Exports
/* harmony default export */ __webpack_exports__["default"] = (code);

