var code = "<h1>document (window.document)</h1>\r\n\r\n\r\n<!-- Свойства объекта document -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"props\"></div>\r\n  <h2>Свойства объекта document</h2>\r\n  <ol>\r\n    <li><a href=\"#bgColor\">document.bgColor</a></li>\r\n    <li><a href=\"#title\">document.title</a></li>\r\n  </ol>\r\n</article>\r\n\r\n\r\n<!-- Методы объекта document -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"methods\"></div>\r\n  <h2>Методы объекта document</h2>\r\n  <ol>\r\n    <li><a href=\"#bgColor\">document.bgColor</a></li>\r\n    <li><a href=\"#title\">document.title</a></li>\r\n  </ol>\r\n</article>\r\n\r\n\r\n<!-- События объекта document -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"events\"></div>\r\n  <h2>События объекта document</h2>\r\n  <ol>\r\n    <li><a href=\"#clear\">document.clear()</a></li>\r\n    <li><a href=\"#close\">document.close()</a></li>\r\n    <li><a href=\"#open\">document.open()</a></li>\r\n    <li><a href=\"#write\">document.write()</a></li>\r\n  </ol>\r\n</article>\r\n\r\n";
