// Module
var code = "<h1>FileReader</h1>\r\n\r\n\r\n<!-- about -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"about\"></div>\r\n  <h2>about</h2>\r\n\r\n  <h4>Пример</h4>\r\n  <p>Создадим в index.html input для выбора файла и div для вывода текста из файла.</p>\r\n  <code>&lt;input type=\"file\" id=\"myFile\"&gt;</code>\r\n  <code>&lt;input type=\"file\" id=\"myFiles\" multiple&gt;</code>\r\n  <code>&lt;div id=\"content\"&gt;&lt;/div&gt;</code>\r\n\r\n  <p>В index.js запишем код</p>\r\n<pre>const output = document.getElementById('content');\r\n\r\n// обработаем выбор одного файла\r\ndocument.getElementById('myFile').onchange = getFile;\r\nfunction getFile(e) {\r\n  const file = e.target.files[0];\r\n  console.log(file.name, file.type, file.size);\r\n  const reader = new FileReader();\r\n  reader.onload = function(ev) {\r\n    output.textContent = ev.target.result;\r\n  };\r\n  reader.readAsText(file);\r\n}\r\n\r\n// обработаем выбор нескольких файлов\r\ndocument.getElementById('myFiles').onchange = getFiles;\r\nfunction getFiles(e) {\r\n  const files = e.target.files;\r\n  for (let i = 0; i &lt; files.length; i++) {\r\n    const file = files[i];\r\n    console.log(file.name, file.type, file.size);\r\n    const reader = new FileReader();\r\n    reader.onload = function(ev) {\r\n      output.textContent += ev.target.result;\r\n    };\r\n    reader.readAsText(file);\r\n  }\r\n}</pre>\r\n</article>\r\n\r\n<!-- Методы FileReader -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"methods\"></div>\r\n  <h2>Методы FileReader</h2>\r\n\r\n  <ol>\r\n    <li><a href=\"#readAsArrayBuffer\">readAsArrayBuffer</a></li>\r\n    <li><a href=\"#readAsBinaryString\">readAsBinaryString</a></li>\r\n    <li><a href=\"#readAsDataURL\">readAsDataURL</a></li>\r\n    <li><a href=\"#readAsText\">readAsText</a></li>\r\n  </ol>\r\n</article>\r\n\r\n";
// Exports
