var code = "<h1>Встроенный объект Screen (window.screen)</h1>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article article__content\">\r\n  <h2>Содержание</h2>\r\n\r\n  <p><a href=\"#props\">Свойства window.screen</a></p>\r\n  <p><a href=\"#methods\">Методы window.screen</a></p>\r\n</article>\r\n\r\n\r\n<!-- Свойства window.screen -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"props\"></div>\r\n  <h2>Свойства window.screen</h2>\r\n\r\n  <ol>\r\n    <li><a href=\"#availHeight\">availHeight</a></li>\r\n    <li><a href=\"#availLeft\">availLeft</a></li>\r\n    <li><a href=\"#availTop\">availTop</a></li>\r\n    <li><a href=\"#availWidth\">availWidth</a></li>\r\n    <li><a href=\"#colorDepth\">colorDepth</a></li>\r\n    <li><a href=\"#height\">height</a></li>\r\n    <li><a href=\"#isExtended\">isExtended</a></li>\r\n    <li><a href=\"#onchange\">onchange</a></li>\r\n    <li><a href=\"#orientation\">orientation</a></li>\r\n    <li><a href=\"#pixelDepth\">pixelDepth</a></li>\r\n    <li><a href=\"#width\">width</a></li>\r\n  </ol>\r\n</article>\r\n\r\n\r\n<!-- Методы window.screen  -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"methods\"></div>\r\n  <h2>Методы window.screen</h2>\r\n</article>\r\n\r\n\r\n";
