var code = "<h1>Объект Error</h1>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n  <p><a href=\"#links\">links</a></p>\r\n  <p><a href=\"#about\">about</a></p>\r\n  <p><a href=\"#try\">try catch</a></p>\r\n  8 встроенных видов ошибок\r\n  <ol>\r\n    <li><a href=\"#error-aggregate\">AggregateError</a></li>\r\n    <li><a href=\"#error-eval\">EvalError</a></li>\r\n    <li><a href=\"#error-internal\">InternalError</a></li>\r\n    <li><a href=\"#error-range\">RangeError</a></li>\r\n    <li><a href=\"#error-reference\">ReferenceError</a></li>\r\n    <li><a href=\"#error-syntax\">SyntaxError</a></li>\r\n    <li><a href=\"#error-type\">TypeError</a></li>\r\n    <li><a href=\"#error-uri\">URIError</a></li>\r\n  </ol>\r\n</article>\r\n\r\n\r\n<!-- links -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"links\"></div>\r\n  <h2>links</h2>\r\n  <p><a href=\"https://developer.mozilla.org/ru/docs/Web/JavaScript/Reference/Global_Objects/Error\">developer.mozilla.org</a></p>\r\n  <p><a href=\"https://learn.javascript.ru/try-catch\">learn.javascript.ru/try-catch</a></p>\r\n  <p><a href=\"https://doka.guide/js/errors/\">doka.guide/js/errors</a></p>\r\n</article>\r\n\r\n\r\n<!-- about -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"about\"></div>\r\n  <h2>about</h2>\r\n  <p>JavaScript умеет обрабатывать некорректный код и сообщать об ошибке в коде. Существует семь встроенных видов ошибок, также можно создать свои собственные. Встроенные ошибки генерируются самим движком JavaScript при выполнении программы, а пользовательские — создаются с помощью конструктора Error. Оба типа ошибок можно ловить в конструкции try...catch.</p>\r\n</article>\r\n\r\n\r\n<!-- try catch -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"try\"></div>\r\n  <h2>try catch</h2>\r\n\r\n  <p>Для отслеживания ошибок нужно использовать блок try catch</p>\r\n<pre>try {\r\n  let x = y // возникнет ошибка, поскольку переменная y не определена\r\n} catch {\r\n  console.log('отловили ошибку')\r\n}\r\nconsole.log('продолжаем программу')\r\n</pre>\r\n</article>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n";
// Exports
/* harmony default export */ __webpack_exports__["default"] = (code);

