var code = "<h1>Задачи на Scope</h1>\r\n\r\n\r\n<article class=\"article\">\r\n  <div id=\"link-to-scope\" class=\"btn-back\">назад</div>\r\n</article>\r\n\r\n\r\n<article class=\"article\">\r\n\r\n\r\n  <h3>Задача 3. Что будет в консоли?</h3>\r\n<pre>console.log(typeof f1);\r\nconsole.log(typeof f2);\r\nconsole.log(typeof f3);\r\n\r\nfunction f1() {}\r\nvar f2 = function() {}\r\nlet f3 = function() {}</pre>\r\n\r\n  <details>\r\n    <summary>Ответ</summary>\r\n<pre>function\r\nundefined\r\nReferenceError: Cannot access 'f3' before initialization</pre>\r\n  </details>\r\n\r\n  \r\n  <h3>Задача 4. Что будет в консоли?</h3>\r\n<pre>var o = {};\r\nvar i = 0;\r\n\r\n(function () {\r\n  o.a = 'a';\r\n  i++;\r\n})();\r\nconsole.log(o, i);\r\n\r\n(function (o,i) {\r\n  o.b = 'b';\r\n  i++;\r\n})(o, i);\r\nconsole.log(o, i);</pre>\r\n\r\n  <details>\r\n    <summary>Ответ</summary>\r\n    <code>{ a: 'a' } 1</code>\r\n    <code>{ a: 'a', b: 'b' } 1</code>\r\n  </details>\r\n</article>\r\n";
