var code = "<h1>Vue</h1>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h2>Содержание</h2>\r\n\r\n  <p><a href=\"#links\">links</a></p>\r\n  <p><a href=\"#about\">about</a></p>\r\n  <p><a href=\"#install\">install</a></p>\r\n</article>\r\n\r\n\r\n<!-- links -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"links\"></div>\r\n  <h2>links</h2>\r\n\r\n  <p><a href=\"https://vuejs.org/\">vuejs.org</a></p>\r\n  <p><a href=\"https://ru.vuejs.org/\">ru.vuejs.org </a>Vue 2</p>\r\n  <p><a href=\"https://v3.ru.vuejs.org/\">v3.ru.vuejs.org</a>Vue 3</p>\r\n\r\n  <h3>Статьи на habr</h3>\r\n\r\n  <p><a href=\"https://habr.com/ru/post/329452/\">Vue.js для сомневающихся. Все, что нужно знать (2017-05-25)</a></p>\r\n  <p><a href=\"https://habr.com/ru/company/ruvds/blog/509700/\">Vue.js для начинающих, урок 1: экземпляр Vue (2020-07-06)</a></p>\r\n  <p><a href=\"https://habr.com/ru/post/543298/\">Улучшение производительности vue приложения (2021-02-19)</a></p>\r\n\r\n  <h3>Статьи</h3>\r\n\r\n  <p><a href=\"https://webdevblog.ru/5-sovetov-po-povysheniju-proizvoditelnosti-vue/\">5 советов по повышению производительности Vue (2021-03-18)</a></p>\r\n</article>\r\n\r\n\r\n<!-- about -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"about\"></div>\r\n  <h2>about</h2>\r\n</article>\r\n\r\n\r\n<!-- install -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"install\"></div>\r\n  <h2>install</h2>\r\n\r\n  <h3>Вариант 1. Подключение через &lt;script&gt;</h3>\r\n  <p><a href=\"https://ru.vuejs.org/v2/guide/installation.html\">https://ru.vuejs.org/v2/guide/installation.html</a></p>\r\n  <p>Просто скачайте JS-файл и подключите его тегом &lt;script&gt; на странице. Будет зарегистрирована глобальная переменная Vue.</p>\r\n  <code>&lt;script src=\"js/vue.js\"&gt;&lt;/script&gt;</code>\r\n\r\n  <h3>Вариант 2. Подключениие через cdn</h3>\r\n  <p><a href=\"https://ru.vuejs.org/v2/guide/installation.html\">https://ru.vuejs.org/v2/guide/installation.html</a></p>\r\n  <code>&lt;script src=\"https://cdn.jsdelivr.net/npm/vue@2.7.0/dist/vue.js\"&gt;&lt;/script&gt;</code>\r\n\r\n  <h3>Вариант 3. Подключениие через npm</h3>\r\n</article>\r\n";
