var code = "<h1>Axios</h1>\r\n\r\n\r\n<!-- Содержание -->\r\n<article class=\"article\">\r\n  <h3>Содержание</h3>\r\n\r\n      <a href=\"#about\">about</a>\r\n  <br><a href=\"#links\">links</a>\r\n  <br><a href=\"#install\">install</a>\r\n</article>\r\n\r\n\r\n<!-- about -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"about\"></div>\r\n  <h3>About</h3>\r\n\r\n  <p>Axios - это HTTP-клиент, основанный на Promise для node.js и браузера. Он изоморфный (= он может работать в браузере и node.js с той же базой кодов). На стороне сервера он использует нативный node.js http-модуль, тогда как на стороне клиента (браузер) он использует XMLHttpRequests.</p>\r\n</article>\r\n\r\n\r\n<!-- links -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"links\"></div>\r\n  <h3>Ссылки</h3>\r\n\r\n  <p><a href=\"https://github.com/axios/axios\">https://github.com/axios/axios</a></p>\r\n  <p><a href=\"https://axios-http.com/ru/\">https://axios-http.com/ru/</a></p>\r\n  <p><a href=\"https://ru.vuejs.org/v2/cookbook/using-axios-to-consume-apis.html\">https://ru.vuejs.org/v2/cookbook/using-axios-to-consume-apis.html</a></p>\r\n\r\n  <h3>Статьи</h3>\r\n  <p><a href=\"https://medium.com/devschacht/%D0%B8%D1%81%D0%BF%D0%BE%D0%BB%D1%8C%D0%B7%D1%83%D0%B5%D0%BC-axios-%D0%B2%D0%BC%D0%B5%D1%81%D1%82%D0%B5-%D1%81-vue-js-3bc45464c460\">Используем axios вместе с Vue.js (2017-09-27)</a></p>\r\n  <p><a href=\"https://habr.com/ru/company/timeweb/blog/571252/\">JavaScript: как из Fetch сделать Axios (2021-08-04)</a></p>\r\n  <p><a href=\"https://habr.com/ru/company/ruvds/blog/477286/\">Axios или Fetch: чем пользоваться в 2019 году (2019-11-29)</a></p>\r\n</article>\r\n\r\n\r\n<!-- inatall -->\r\n<article class=\"article\">\r\n  <div class=\"anchor\" id=\"install\"></div>\r\n  <h3>Установка Axios</h3>\r\n\r\n  <h3>Подключение через &lt;script&gt;</h3>\r\n  <p><a href=\"https://axios-http.com/ru/docs/intro\">https://axios-http.com/ru/docs/intro</a></p>\r\n  <p>Просто скачайте JS-файл и подключите его тегом &lt;script&gt; на странице.</p>\r\n  <code>&lt;script src=\"js/axios.min.js\"&gt;&lt;/script&gt;</code>\r\n\r\n  <h3>Подключениие через jsDelivr CDN</h3>\r\n  <p><a href=\"https://axios-http.com/ru/docs/intro\">https://axios-http.com/ru/docs/intro</a></p>\r\n  <code>&lt;script src=\"https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js\"&gt;&lt;/script&gt;</code>\r\n\r\n  <h3>Подключениие через unpkg CDN</h3>\r\n  <p><a href=\"https://axios-http.com/ru/docs/intro\">https://axios-http.com/ru/docs/intro</a></p>\r\n  <code>&lt;script src=\"https://unpkg.com/axios/dist/axios.min.js\"&gt;&lt;/script&gt;</code>\r\n</article>\r\n";
// Exports
/* harmony default export */ __webpack_exports__["default"] = (code);

